def _runtime_makefile_host_authored(repo: Path, ir_ref: str) -> bool:
    """`record_launch`'s `_resolved_makefile_host_authored`, via the REAL predicate.

    This used to reconstruct the inline expression verbatim, and a reconstruction is only as
    good as its last update: it was wrong once (it omitted the build_system normalization, so
    the test agreed with itself exactly where the live pair diverges), and when the conductor
    moved to the registry it went on comparing against `(make, fortran)` — so a registry
    declaration that made the live pair disagree could not be seen by the test whose whole
    purpose is to see it. `control_file_host_authored` is now named in `orchestration_runtime` and
    called by `record_launch`, so what is compared here is the shipped predicate. Only the two
    READERS (which resolve the values, and normalize the way record_launch does) are mirrored."""
    from tools.orchestration_runtime import (
        _impl_resolved_build_system, _impl_resolved_language, control_file_host_authored)
    bs_resolved = _impl_resolved_build_system(repo, ir_ref)
    lang = _impl_resolved_language(repo, ir_ref)
    bs = (bs_resolved or "").strip().lower() if isinstance(bs_resolved, str) else ""
    return control_file_host_authored(bs, lang)


class WriteRunnerTest(unittest.TestCase):
    """R1/M3c-β: the conductor host-renders `<spec_id>_runner.f90` for an M3c physics node
    (make+fortran, non-infra, exactly one infrastructure/harness dep), and the Makefile
    compiles the leaf-authored `<spec_id>_checks.f90` between model and runner."""

    SID = "boundary_x"

    def _conductor(self, repo: Path) -> _FakeConductor:
        c = _FakeConductor(repo_root=repo, orchestration_id="o",
                           orchestration_agent_run_id="ORCH", llm_config=_cfg("claude"), env={})
        c.calls = []
        return c

    def _refs(self) -> wc.NodeRefs:
        return wc.NodeRefs(
            node_key=f"component/{self.SID}@0.1.0", spec_path=f"spec/component/{self.SID}",
            ir_id="i1", pipeline_id="p1", source_id="s1", binary_id="b1")

    def _write_consumer_ir(self, repo: Path, refs: wc.NodeRefs, *, infra=1,
                           bare_string: bool = False, spec_kind: str | None = None,
                           language: str | None = None) -> None:
        from tools.tests.test_fortran_runner import _boundary_ir
        import yaml as _yaml
        ir = _boundary_ir()
        if spec_kind is not None:
            ir.setdefault("meta", {})["spec_kind"] = spec_kind
        if language is not None:
            ir.setdefault("impl_defaults", {}).setdefault("toolchain", {})["language"] = language
        ids = ["harness_fortran_cpu"] * infra
        if infra == 2:
            ids = ["harness_fortran_cpu", "harness_other_cpu"]
        if bare_string:  # deps.yaml also permits a bare `infrastructure/<id>@ver` string
            deps: list = [f"infrastructure/{i}@0.2.0" for i in ids]
        else:
            deps = [{"node_key": f"infrastructure/{i}@0.2.0"} for i in ids]
        ir["dependency"]["direct_deps"] = deps
        ir_dir = repo / refs.ir_ref
        ir_dir.mkdir(parents=True, exist_ok=True)
        (ir_dir / "spec.ir.yaml").write_text(_yaml.safe_dump(ir), encoding="utf-8")

    def _seed_harness_pipeline(
            self, repo: Path, *, tamper_source: bool = False,
            ir_dirname: str = "harness-fortran-cpu_20260707_002",
            ir_meta_status: str | None = "pass", write_ir_meta: bool = True,
            extra_source_meta: dict | None = None, signatures: object = None,
            no_public_api_signatures: bool = False,
            binary_source_ir_id: str | None = "harness-fortran-cpu_20260707_002",
            write_source_ir_id: bool = True) -> None:
        """Seed a ready certified-harness pipeline + its certified IR dir.

        `source_meta.json` is written CONTRACT-MINIMAL (no `ir_ref`): the pin resolves the IR
        structurally, never from source_meta. `binary_meta.source_ir_id` (host-authored) binds the
        certified binary to its origin IR dir under `workspace/ir/<safe>/<binary_source_ir_id>`;
        `write_source_ir_id=False` omits it to exercise the legacy `_certified_ir_dir` fallback.
        `ir_dirname` (the seeded IR dir) may diverge from the pipeline dir name (compile reopen
        re-numbers ir_id independently). `extra_source_meta` merges extra keys into the (still
        ir_ref-free) source_meta to prove they are ignored."""
        from tools.tests.test_fortran_runner import (
            _HARNESS_STUB, _harness_signatures)
        import yaml as _yaml
        safe = "infrastructure__harness_fortran_cpu__0.2.0"
        pipe = repo / "workspace" / "pipelines" / safe / "harness-fortran-cpu_20260707_002"
        src_dir = pipe / "source" / "src_20260707_002" / "src"
        src_dir.mkdir(parents=True, exist_ok=True)
        source = _HARNESS_STUB
        if tamper_source:
            source = source.replace(
                "function harness_fortran_cpu__box(name, json) result(nv)",
                "function harness_fortran_cpu__box(key, json) result(nv)")
        (src_dir / "harness_fortran_cpu_model.f90").write_text(source, encoding="utf-8")
        smeta: dict = dict(extra_source_meta or {})  # contract-minimal: NO ir_ref
        (src_dir.parent / "source_meta.json").write_text(
            json.dumps(smeta), encoding="utf-8")
        (pipe / "binary" / "bin_20260707_001").mkdir(parents=True, exist_ok=True)
        bmeta: dict = {"source_source_id": "src_20260707_002"}
        if write_source_ir_id and binary_source_ir_id is not None:
            bmeta["source_ir_id"] = binary_source_ir_id
        (pipe / "binary" / "bin_20260707_001" / "binary_meta.json").write_text(
            json.dumps(bmeta), encoding="utf-8")
        hir_dir = repo / "workspace" / "ir" / safe / ir_dirname
        hir_dir.mkdir(parents=True, exist_ok=True)
        sigs = _harness_signatures() if signatures is None else signatures
        pub = {} if no_public_api_signatures else {"signatures": sigs}
        (hir_dir / "spec.ir.yaml").write_text(
            _yaml.safe_dump({"public_api": pub}), encoding="utf-8")
        if write_ir_meta:
            (hir_dir / "ir_meta.json").write_text(
                json.dumps({"verification_status": ir_meta_status}), encoding="utf-8")

    def test_conductor_authors_runner_truth_matrix(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            refs = self._refs()
            c = self._conductor(repo)
            self._write_consumer_ir(repo, refs, infra=1)
            self.assertTrue(c._conductor_authors_runner(refs))
            # Zero / two infra deps -> not M3c, so the conductor does not host-render. Neither
            # count can reach here from a live run any more (spec-input rejects both), but the
            # predicate must stay fail-safe for a hand-crafted IR: it declines to render rather
            # than rendering glue against a harness it cannot identify.
            self._write_consumer_ir(repo, refs, infra=0)
            self.assertFalse(c._conductor_authors_runner(refs))
            self._write_consumer_ir(repo, refs, infra=2)
            self.assertFalse(c._conductor_authors_runner(refs))

    def test_conductor_authors_runner_bare_string_dep_parity(self) -> None:
        # deps.yaml permits a bare-string infra dep as well as the dict form; the conductor
        # predicate must count it identically to the gate (a divergence = host-render vs
        # checks-gate skew = fail-open). Locks the prior HIGH parity bug's fix.
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            refs = self._refs()
            c = self._conductor(repo)
            self._write_consumer_ir(repo, refs, infra=1, bare_string=True)
            self.assertTrue(c._conductor_authors_runner(refs))
            self._write_consumer_ir(repo, refs, infra=2, bare_string=True)
            self.assertFalse(c._conductor_authors_runner(refs))

    def test_conductor_authors_runner_false_for_infra_node(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            refs = self._refs()
            from tools.tests.test_fortran_runner import _boundary_ir
            import yaml as _yaml
            ir = _boundary_ir()
            ir["meta"]["spec_kind"] = "infrastructure"
            ir["dependency"]["direct_deps"] = [
                {"node_key": "infrastructure/harness_fortran_cpu@0.2.0"}]
            (repo / refs.ir_ref).mkdir(parents=True, exist_ok=True)
            (repo / refs.ir_ref / "spec.ir.yaml").write_text(_yaml.safe_dump(ir))
            self.assertFalse(self._conductor(repo)._conductor_authors_runner(refs))

    def test_write_runner_renders_through_the_NODE_S_language_backend(self) -> None:
        """`_write_runner` hands the seam the language it read, and does not assume one.

        Measured before this existed: replacing `language = _ir_language(ir)` with a fixed value
        left the suite green in any spelling the sampled token ratchet cannot see — and the
        ratchet is documented as a bound on growth, not a detector. With one language backend
        the two are indistinguishable, so a second is synthesised: its renderer emits text the
        real one never would, and its pin accepts anything, so the only thing the assertion can
        be observing is which backend was dispatched to.
        """
        import sys
        import types

        from tools.backends import registry as backend_registry

        other = types.ModuleType("zz_write_runner_lang")
        runner = types.ModuleType("zz_write_runner_lang.runner")
        runner.CHECKS_PUBLIC_NAMES = ("zz_abi",)
        runner.render_runner = lambda ir, spec_id, harness: f"! rendered by zz for {spec_id}\n"
        runner.assert_harness_pin = lambda *a, **k: None
        runner.ir_content_violations = lambda *a, **k: []
        other.runner = runner
        record = backend_registry.Backend(
            "language", "zz_wr", "zz_write_runner_lang",
            core_provides=frozenset({"control_file"}),
            backend_provides=frozenset({"runner_render"}))
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            refs = self._refs()
            self._write_consumer_ir(repo, refs, infra=1, language="zz_wr")
            self._seed_harness_pipeline(repo)
            with mock.patch.dict(sys.modules, {"zz_write_runner_lang": other}), \
                    mock.patch.dict(
                        backend_registry._BACKENDS, {("language", "zz_wr"): record}):
                c = self._conductor(repo)
                self.assertTrue(c._conductor_authors_runner(refs))
                c._write_runner(refs)
            text = (repo / refs.source_dir() / "src"
                    / f"{self.SID}_runner.f90").read_text(encoding="utf-8")
        self.assertEqual(f"! rendered by zz for {self.SID}\n", text)

    def test_write_runner_names_a_declaration_that_outruns_its_package(self) -> None:
        """The clauses added to fix the previous round, which were themselves unobserved.

        A record can declare `runner_render` in `backend_provides` while its package carries no
        renderer: the registry refuses to import a backend at declaration time, so nothing can
        catch that until something dispatches. `_conductor_authors_runner` approves the node on
        the declaration and the seam then refuses it. Both entries into the seam must say so as
        a build precondition — an operator fixes the record or the package — rather than reaching
        the conductor's generic handler, which reports it as a render failure and points a reader
        at the IR.

        ONE clause, at `assert_harness_pin` — which is the unconditional first entry into the
        seam, so a backend that cannot be dispatched to has already raised by the time the render
        call is reached. A second clause was written around the render call and measured
        unreachable; it was deleted rather than given a witness it cannot have.
        """
        import sys
        import types

        from tools.backends import registry as backend_registry

        hollow = types.ModuleType("zz_hollow_runner_pkg")  # declares the job, carries nothing
        record = backend_registry.Backend(
            "language", "zz_hollow", "zz_hollow_runner_pkg",
            core_provides=frozenset({"control_file"}),
            backend_provides=frozenset({"runner_render"}))
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            refs = self._refs()
            self._write_consumer_ir(repo, refs, infra=1, language="zz_hollow")
            self._seed_harness_pipeline(repo)
            with mock.patch.dict(sys.modules, {"zz_hollow_runner_pkg": hollow}), \
                    mock.patch.dict(
                        backend_registry._BACKENDS, {("language", "zz_hollow"): record}):
                c = self._conductor(repo)
                # the authorship predicate approves it — that is the premise, not a bug
                self.assertTrue(c._conductor_authors_runner(refs))
                with self.assertRaises(RuntimeError) as ctx:
                    c._write_runner(refs)
        message = str(ctx.exception)
        self.assertIn("cannot be dispatched to", message)
        self.assertIn("zz_hollow", message)

    def test_write_runner_renders_and_pins(self) -> None:
        from tools.backends.language.fortran.runner import render_runner
        from tools.tests.test_fortran_runner import _boundary_ir
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            refs = self._refs()
