            for sub, fname in (("pre_judge", "pre_judge_meta.json"),
                               ("post_judge", "post_judge_meta.json")):
                p = rn / fname
                paths = [refs.run_node_dir() + "/" + fname]
                p.write_text(json.dumps({"status": "pass"}), encoding="utf-8")
